def factorial(n):
    # base case
    if n == 0:
        return 1

    # recursive case
    else:
        return n*factorial(n - 1)

# Input a number
num = int(input('Enter a number: '))

# Output factorial of the number
print('The factorial of', num, 'is', factorial(num))

def remove_a(string):
